import {
  StreamingState,
  StreamChunk,
  UseStreamingOptions,
} from "../types/streaming";
import { useAIProviderStore } from "../stores/provider-store";
import { useState, useCallback, useRef } from "react";

export function useAIStreaming(options?: UseStreamingOptions) {
  const [state, setState] = useState<StreamingState>("idle");
  const [content, setContent] = useState("");
  const [error, setError] = useState<string | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);
  const getNextFallback = useAIProviderStore((s) => s.getNextFallback);

  const startStream = useCallback(
    async (
      modelId: string,
      message: string,
      history?: Array<{ role: string; content: string }>,
    ) => {
      if (state === "streaming") return;
      setState("connecting");
      setError(null);
      setContent("");

      const controller = new AbortController();
      abortControllerRef.current = controller;

      try {
        // Use SSE endpoint
        const params = new URLSearchParams({ message });
        if (history) params.set("history", JSON.stringify(history));

        // Raw fetch: SSE response is read incrementally via response.body
        const response = await fetch(
          `/api/ai/stream/${modelId}/chat?${params}`,
          {
            signal: controller.signal,
          },
        );

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        setState("streaming");
        const reader = response.body?.getReader();
        if (!reader) throw new Error("No readable stream");

        const decoder = new TextDecoder();
        let buffer = "";

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split("\n");
          buffer = lines.pop() || "";

          for (const line of lines) {
            if (!line.startsWith("data: ")) continue;
            const data = line.slice(6);
            if (data === "[DONE]") {
              setState("complete");
              options?.onComplete?.(content);
              break;
            }
            try {
              const chunk: StreamChunk = JSON.parse(data);
              setContent((prev) => {
                const newContent = prev + chunk.content;
                options?.onChunk?.(chunk);
                return newContent;
              });
            } catch {
              // Skip malformed JSON
            }
          }
        }

        setState("complete");
      } catch (err) {
        if (err instanceof Error && err.name !== "AbortError") {
          setError(err.message);
          setState("error");
          options?.onError?.(err);
          // Try fallback provider
          const fallback = getNextFallback();
          if (fallback) {
            await startStream(modelId, message, history);
          }
        }
      }
    },
    [state, getNextFallback, options, content],
  );

  const abort = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      setState("error");
      setError("Stream aborted");
    }
  }, []);

  const reset = useCallback(() => {
    setState("idle");
    setContent("");
    setError(null);
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
  }, []);

  return { state, content, error, startStream, abort, reset };
}
